//! Snappy decompression.
//!
//! Provides decompression support for Snappy compressed data in the raw
//! (unframed) format, as described by the Snappy format description
//! (https://github.com/google/snappy/tree/main/format_description).
//!
//! The compressed format consisting of a variable-length integer for the
//! uncompressed data size followed by a series of literal and copy
//! operations:
//!
//! - Literal (`tag & 0b11 == 0b00`): `len = (tag >> 2) + 1` for
//!   `tag < 1<<6` and for `tag >= 1<<6` the next `1 - (tag >> 6)` bytes
//!   (up to four) contain `len - 1` as a little-endian integer.
//!   Followed by `len` literal bytes.
//! - Copy1 (`tag & 0b11 == 0b01`): `len = ((tag >> 2) & 0b111) + 4` (4-11
//!   bytes) with a back-reference offset of `((tag >> 5) & 0b111) << 8`
//!   combined with a single following byte (8-111).
//! - Copy2 (`tag & 0b11 == 0b10`): `len = (tag >> 2) + 1` (1-64 bytes) with
//!   a two-byte little-endian back-reference offset.
//! - Copy4 (`tag & 0b11 == 0b11`): `len = (tag >> 2) + 1` (1-64 bytes) with
//!   a four-byte little-endian back-reference offset.
//!
//! Copy operations are back-references into the already emitted output and
//! may overlap the copied region (i.e. they replicate the referenced bytes).
//!
//! The decoder is strict: it rejects truncated streams, overlong declarations,
//! invalid copy offsets, lengths that exceed the remaining output and
//! trailing data after the last operation.

use keramics_core::ErrorTrace;

/// Maximum uncompressed data size in bytes (2^32 - 1).
const SNAPPY_MAX_INPUT_SIZE: u64 = (1 << 32) - 1;

/// Maximum number of bytes used to encode a variable-length integer.
const SNAPPY_MAX_VARINT_SIZE: usize = 5;

/// Maximum literal length encoded directly in the tag (1-60 bytes).
const SNAPPY_LITERAL_MAX_DIRECT_LENGTH: u8 = 60;

/// Context for decompressing Snappy compressed data.
pub struct SnappyContext {
    /// Uncompressed data size.
    pub uncompressed_data_size: usize,
}

impl SnappyContext {
    /// Creates a new context.
    pub fn new() -> Self {
        Self {
            uncompressed_data_size: 0,
        }
    }

    /// Decompress data.
    ///
    /// The `uncompressed_data` slice must already be sized to the expected
    /// uncompressed output.
    pub fn decompress(
        &mut self,
        compressed_data: &[u8],
        uncompressed_data: &mut [u8],
    ) -> Result<(), ErrorTrace> {
        if compressed_data.is_empty() {
            return Err(keramics_core::error_trace_new!(
                "Invalid compressed data value too small"
            ));
        }
        let mut offset: usize = 0;
        let uncompressed_data_size: u64 = Self::read_varint(compressed_data, &mut offset)?;
        if uncompressed_data_size > SNAPPY_MAX_INPUT_SIZE {
            return Err(keramics_core::error_trace_new!(
                "Invalid uncompressed data size value too large"
            ));
        }
        if uncompressed_data_size as usize != uncompressed_data.len() {
            return Err(keramics_core::error_trace_new!(format!(
                "Invalid uncompressed data size ({} != {})",
                uncompressed_data_size,
                uncompressed_data.len()
            )));
        }
        if uncompressed_data_size == 0 {
            self.uncompressed_data_size = 0;
            return Ok(());
        }

        let input_size: usize = compressed_data.len();
        let uncompressed_end: usize = uncompressed_data.len();
        let mut output_size: usize = 0;

        while offset < input_size {
            let tag: u8 = compressed_data[offset];
            offset += 1;

            match tag & 0b0000_0011 {
                0b00 => {
                    let literal_length: usize;
                    let extra: u8 = tag >> 2;
                    if extra < SNAPPY_LITERAL_MAX_DIRECT_LENGTH {
                        literal_length = usize::from(extra) + 1;
                    } else {
                        let number_of_length_bytes: usize =
                            usize::from(extra - SNAPPY_LITERAL_MAX_DIRECT_LENGTH + 1);
                        if offset + number_of_length_bytes > input_size {
                            return Err(keramics_core::error_trace_new!(
                                "Invalid compressed data value too small"
                            ));
                        }
                        let mut length_value: u64 = 0;
                        for byte_index in 0..number_of_length_bytes {
                            length_value = length_value
                                | (u64::from(compressed_data[offset + byte_index])
                                    << (8 * byte_index));
                        }
                        if length_value > SNAPPY_MAX_INPUT_SIZE {
                            return Err(keramics_core::error_trace_new!(
                                "Invalid uncompressed data size value too large"
                            ));
                        }
                        offset += number_of_length_bytes;
                        literal_length = length_value as usize + 1;
                    }
                    if output_size + literal_length > uncompressed_end {
                        return Err(keramics_core::error_trace_new!(
                            "Invalid literal length value too large"
                        ));
                    }
                    if offset + literal_length > input_size {
                        return Err(keramics_core::error_trace_new!(
                            "Invalid compressed data value too small"
                        ));
                    }
                    uncompressed_data[output_size..(output_size + literal_length)]
                        .copy_from_slice(&compressed_data[offset..(offset + literal_length)]);
                    offset += literal_length;
                    output_size += literal_length;
                }
                0b01 => {
                    let copy_length: usize = ((tag >> 2) & 0b111) as usize + 4;
                    if offset >= input_size {
                        return Err(keramics_core::error_trace_new!(
                            "Invalid compressed data value too small"
                        ));
                    }
                    let copy_offset: usize = ((((tag >> 5) & 0b111) as usize) << 8)
                        | usize::from(compressed_data[offset]);
                    offset += 1;
                    Self::validate_and_emit_copy(
                        uncompressed_data,
                        output_size,
                        copy_length,
                        copy_offset,
                    )?;
                    output_size += copy_length;
                }
                0b10 => {
                    let copy_length: usize = usize::from(tag >> 2) + 1;
                    if offset + 2 > input_size {
                        return Err(keramics_core::error_trace_new!(
                            "Invalid compressed data value too small"
                        ));
                    }
                    let copy_offset: usize = usize::from(compressed_data[offset])
                        | (usize::from(compressed_data[offset + 1]) << 8);
                    offset += 2;
                    Self::validate_and_emit_copy(
                        uncompressed_data,
                        output_size,
                        copy_length,
                        copy_offset,
                    )?;
                    output_size += copy_length;
                }
                _ => {
                    let copy_length: usize = usize::from(tag >> 2) + 1;
                    if offset + 4 > input_size {
                        return Err(keramics_core::error_trace_new!(
                            "Invalid compressed data value too small"
                        ));
                    }
                    let copy_offset: usize = usize::from(compressed_data[offset])
                        | (usize::from(compressed_data[offset + 1]) << 8)
                        | (usize::from(compressed_data[offset + 2]) << 16)
                        | (usize::from(compressed_data[offset + 3]) << 24);
                    offset += 4;
                    Self::validate_and_emit_copy(
                        uncompressed_data,
                        output_size,
                        copy_length,
                        copy_offset,
                    )?;
                    output_size += copy_length;
                }
            }
        }
        if output_size != uncompressed_data.len() {
            return Err(keramics_core::error_trace_new!(format!(
                "Invalid compressed data output size ({}) does not match declared size ({})",
                output_size,
                uncompressed_data.len()
            )));
        }
        self.uncompressed_data_size = uncompressed_data.len();

        Ok(())
    }

    /// Reads a variable-length integer.
    fn read_varint(data: &[u8], offset: &mut usize) -> Result<u64, ErrorTrace> {
        let mut value: u64 = 0;
        let mut shift: u32 = 0;

        for _ in 0..SNAPPY_MAX_VARINT_SIZE {
            if *offset >= data.len() {
                return Err(keramics_core::error_trace_new!(
                    "Invalid compressed data value too small"
                ));
            }
            let byte: u8 = data[*offset];
            *offset += 1;
            value |= u64::from(byte & 0b0111_1111) << shift;
            if byte & 0b1000_0000 == 0 {
                return Ok(value);
            }
            shift += 7;
        }
        Err(keramics_core::error_trace_new!(
            "Invalid variable-length integer value too long"
        ))
    }

    /// Validates a copy operation and emits the copied (possibly overlapping) bytes.
    fn validate_and_emit_copy(
        uncompressed_data: &mut [u8],
        output_size: usize,
        copy_length: usize,
        copy_offset: usize,
    ) -> Result<(), ErrorTrace> {
        if copy_offset == 0 {
            return Err(keramics_core::error_trace_new!(
                "Invalid copy offset value too small"
            ));
        }
        if copy_offset > output_size {
            return Err(keramics_core::error_trace_new!(format!(
                "Invalid copy offset ({}) greater than output size ({})",
                copy_offset, output_size
            )));
        }
        if output_size + copy_length > uncompressed_data.len() {
            return Err(keramics_core::error_trace_new!(
                "Invalid copy length value too large"
            ));
        }
        // The copy offset is the distance back from the end of the emitted
        // output to the start of the source region, so the source region is
        // [output_size - copy_offset, output_size - copy_offset + copy_length).
        // Copying byte-by-byte keeps overlapping sources (which replicate the
        // referenced bytes) correct.
        let source_start: usize = output_size - copy_offset;
        for copy_byte_index in 0..copy_length {
            let source_byte: u8 = uncompressed_data[source_start + copy_byte_index];
            uncompressed_data[output_size + copy_byte_index] = source_byte;
        }
        Ok(())
    }
}

